package com.lumobrowser.app.feedback

import androidx.annotation.RawRes
import com.lumobrowser.app.R
import com.lumobrowser.app.data.SoundStyle

/**
 * Maps a [SoundCue] and a [SoundStyle] to the generated asset for that pair.
 *
 * Generated by `tools/generate_sound_library.py` from the files actually present in
 * `res/raw`. Do not edit by hand: the table has one entry per cue/style pair and a
 * hand-edited version can silently pair a cue with the wrong style, which compiles and
 * sounds wrong. `SoundLibraryTest` re-derives the expected resource names from the
 * enums and fails if this table and the asset set ever disagree.
 */
internal object SoundLibrary {

    /** Every cue in every style. Never returns 0: the coverage is asserted by a test. */
    @RawRes
    fun rawFor(cue: SoundCue, style: SoundStyle): Int = when (cue) {
        SoundCue.Press -> when (style) {
            SoundStyle.Soft -> R.raw.sfx_press_soft
            SoundStyle.Crisp -> R.raw.sfx_press_crisp
            SoundStyle.Glass -> R.raw.sfx_press_glass
            SoundStyle.Deep -> R.raw.sfx_press_deep
        }
        SoundCue.Release -> when (style) {
            SoundStyle.Soft -> R.raw.sfx_release_soft
            SoundStyle.Crisp -> R.raw.sfx_release_crisp
            SoundStyle.Glass -> R.raw.sfx_release_glass
            SoundStyle.Deep -> R.raw.sfx_release_deep
        }
        SoundCue.Click -> when (style) {
            SoundStyle.Soft -> R.raw.sfx_click_soft
            SoundStyle.Crisp -> R.raw.sfx_click_crisp
            SoundStyle.Glass -> R.raw.sfx_click_glass
            SoundStyle.Deep -> R.raw.sfx_click_deep
        }
        SoundCue.Toggle -> when (style) {
            SoundStyle.Soft -> R.raw.sfx_toggle_soft
            SoundStyle.Crisp -> R.raw.sfx_toggle_crisp
            SoundStyle.Glass -> R.raw.sfx_toggle_glass
            SoundStyle.Deep -> R.raw.sfx_toggle_deep
        }
        SoundCue.Navigate -> when (style) {
            SoundStyle.Soft -> R.raw.sfx_navigate_soft
            SoundStyle.Crisp -> R.raw.sfx_navigate_crisp
            SoundStyle.Glass -> R.raw.sfx_navigate_glass
            SoundStyle.Deep -> R.raw.sfx_navigate_deep
        }
        SoundCue.DialogOpen -> when (style) {
            SoundStyle.Soft -> R.raw.sfx_dialog_open_soft
            SoundStyle.Crisp -> R.raw.sfx_dialog_open_crisp
            SoundStyle.Glass -> R.raw.sfx_dialog_open_glass
            SoundStyle.Deep -> R.raw.sfx_dialog_open_deep
        }
        SoundCue.DialogClose -> when (style) {
            SoundStyle.Soft -> R.raw.sfx_dialog_close_soft
            SoundStyle.Crisp -> R.raw.sfx_dialog_close_crisp
            SoundStyle.Glass -> R.raw.sfx_dialog_close_glass
            SoundStyle.Deep -> R.raw.sfx_dialog_close_deep
        }
        SoundCue.BookmarkAdded -> when (style) {
            SoundStyle.Soft -> R.raw.sfx_bookmark_added_soft
            SoundStyle.Crisp -> R.raw.sfx_bookmark_added_crisp
            SoundStyle.Glass -> R.raw.sfx_bookmark_added_glass
            SoundStyle.Deep -> R.raw.sfx_bookmark_added_deep
        }
        SoundCue.SettingsSaved -> when (style) {
            SoundStyle.Soft -> R.raw.sfx_settings_saved_soft
            SoundStyle.Crisp -> R.raw.sfx_settings_saved_crisp
            SoundStyle.Glass -> R.raw.sfx_settings_saved_glass
            SoundStyle.Deep -> R.raw.sfx_settings_saved_deep
        }
        SoundCue.Confirm -> when (style) {
            SoundStyle.Soft -> R.raw.sfx_confirm_soft
            SoundStyle.Crisp -> R.raw.sfx_confirm_crisp
            SoundStyle.Glass -> R.raw.sfx_confirm_glass
            SoundStyle.Deep -> R.raw.sfx_confirm_deep
        }
        SoundCue.DeleteConfirm -> when (style) {
            SoundStyle.Soft -> R.raw.sfx_delete_confirm_soft
            SoundStyle.Crisp -> R.raw.sfx_delete_confirm_crisp
            SoundStyle.Glass -> R.raw.sfx_delete_confirm_glass
            SoundStyle.Deep -> R.raw.sfx_delete_confirm_deep
        }
        SoundCue.Error -> when (style) {
            SoundStyle.Soft -> R.raw.sfx_error_soft
            SoundStyle.Crisp -> R.raw.sfx_error_crisp
            SoundStyle.Glass -> R.raw.sfx_error_glass
            SoundStyle.Deep -> R.raw.sfx_error_deep
        }
        SoundCue.LoadStart -> when (style) {
            SoundStyle.Soft -> R.raw.sfx_load_start_soft
            SoundStyle.Crisp -> R.raw.sfx_load_start_crisp
            SoundStyle.Glass -> R.raw.sfx_load_start_glass
            SoundStyle.Deep -> R.raw.sfx_load_start_deep
        }
        SoundCue.LoadSuccess -> when (style) {
            SoundStyle.Soft -> R.raw.sfx_load_success_soft
            SoundStyle.Crisp -> R.raw.sfx_load_success_crisp
            SoundStyle.Glass -> R.raw.sfx_load_success_glass
            SoundStyle.Deep -> R.raw.sfx_load_success_deep
        }
        SoundCue.LoadFailure -> when (style) {
            SoundStyle.Soft -> R.raw.sfx_load_failure_soft
            SoundStyle.Crisp -> R.raw.sfx_load_failure_crisp
            SoundStyle.Glass -> R.raw.sfx_load_failure_glass
            SoundStyle.Deep -> R.raw.sfx_load_failure_deep
        }
        SoundCue.VpnConnecting -> when (style) {
            SoundStyle.Soft -> R.raw.sfx_vpn_connecting_soft
            SoundStyle.Crisp -> R.raw.sfx_vpn_connecting_crisp
            SoundStyle.Glass -> R.raw.sfx_vpn_connecting_glass
            SoundStyle.Deep -> R.raw.sfx_vpn_connecting_deep
        }
        SoundCue.VpnConnected -> when (style) {
            SoundStyle.Soft -> R.raw.sfx_vpn_connected_soft
            SoundStyle.Crisp -> R.raw.sfx_vpn_connected_crisp
            SoundStyle.Glass -> R.raw.sfx_vpn_connected_glass
            SoundStyle.Deep -> R.raw.sfx_vpn_connected_deep
        }
        SoundCue.VpnFailed -> when (style) {
            SoundStyle.Soft -> R.raw.sfx_vpn_failed_soft
            SoundStyle.Crisp -> R.raw.sfx_vpn_failed_crisp
            SoundStyle.Glass -> R.raw.sfx_vpn_failed_glass
            SoundStyle.Deep -> R.raw.sfx_vpn_failed_deep
        }
        SoundCue.LaunchEnd -> when (style) {
            SoundStyle.Soft -> R.raw.sfx_launch_end_soft
            SoundStyle.Crisp -> R.raw.sfx_launch_end_crisp
            SoundStyle.Glass -> R.raw.sfx_launch_end_glass
            SoundStyle.Deep -> R.raw.sfx_launch_end_deep
        }
    }

    /** Every asset, for preloading. Order is stable so warm-up is reproducible. */
    val all: List<Int> = listOf(
        R.raw.sfx_press_soft, R.raw.sfx_press_crisp, R.raw.sfx_press_glass, R.raw.sfx_press_deep,
        R.raw.sfx_release_soft, R.raw.sfx_release_crisp, R.raw.sfx_release_glass, R.raw.sfx_release_deep,
        R.raw.sfx_click_soft, R.raw.sfx_click_crisp, R.raw.sfx_click_glass, R.raw.sfx_click_deep,
        R.raw.sfx_toggle_soft, R.raw.sfx_toggle_crisp, R.raw.sfx_toggle_glass, R.raw.sfx_toggle_deep,
        R.raw.sfx_navigate_soft, R.raw.sfx_navigate_crisp, R.raw.sfx_navigate_glass, R.raw.sfx_navigate_deep,
        R.raw.sfx_dialog_open_soft, R.raw.sfx_dialog_open_crisp, R.raw.sfx_dialog_open_glass, R.raw.sfx_dialog_open_deep,
        R.raw.sfx_dialog_close_soft, R.raw.sfx_dialog_close_crisp, R.raw.sfx_dialog_close_glass, R.raw.sfx_dialog_close_deep,
        R.raw.sfx_bookmark_added_soft, R.raw.sfx_bookmark_added_crisp, R.raw.sfx_bookmark_added_glass, R.raw.sfx_bookmark_added_deep,
        R.raw.sfx_settings_saved_soft, R.raw.sfx_settings_saved_crisp, R.raw.sfx_settings_saved_glass, R.raw.sfx_settings_saved_deep,
        R.raw.sfx_confirm_soft, R.raw.sfx_confirm_crisp, R.raw.sfx_confirm_glass, R.raw.sfx_confirm_deep,
        R.raw.sfx_delete_confirm_soft, R.raw.sfx_delete_confirm_crisp, R.raw.sfx_delete_confirm_glass, R.raw.sfx_delete_confirm_deep,
        R.raw.sfx_error_soft, R.raw.sfx_error_crisp, R.raw.sfx_error_glass, R.raw.sfx_error_deep,
        R.raw.sfx_load_start_soft, R.raw.sfx_load_start_crisp, R.raw.sfx_load_start_glass, R.raw.sfx_load_start_deep,
        R.raw.sfx_load_success_soft, R.raw.sfx_load_success_crisp, R.raw.sfx_load_success_glass, R.raw.sfx_load_success_deep,
        R.raw.sfx_load_failure_soft, R.raw.sfx_load_failure_crisp, R.raw.sfx_load_failure_glass, R.raw.sfx_load_failure_deep,
        R.raw.sfx_vpn_connecting_soft, R.raw.sfx_vpn_connecting_crisp, R.raw.sfx_vpn_connecting_glass, R.raw.sfx_vpn_connecting_deep,
        R.raw.sfx_vpn_connected_soft, R.raw.sfx_vpn_connected_crisp, R.raw.sfx_vpn_connected_glass, R.raw.sfx_vpn_connected_deep,
        R.raw.sfx_vpn_failed_soft, R.raw.sfx_vpn_failed_crisp, R.raw.sfx_vpn_failed_glass, R.raw.sfx_vpn_failed_deep,
        R.raw.sfx_launch_end_soft, R.raw.sfx_launch_end_crisp, R.raw.sfx_launch_end_glass, R.raw.sfx_launch_end_deep,
    )
}
